import {Port} from '../../core/index.js';import {THREE,mesh,slab,materials,portQuaternion,ringY,cappedSweep,annulus,solid,roundedRect,hole}from'./geometry.js';import{spec}from'./dimensions.js';const tau=Math.PI*2;
export function grove(host){const frame=new THREE.Group();frame.name='CatM GNSS actual blue open Grove receiver';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(portQuaternion('bottom'));host.body.add(frame);const blue=materials.plastic(0x049dcc),metal=materials.metal(0xbdb898),box=(s,p,n,m=blue)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'CatM GNSS Grove '+n),rails=[];for(const sign of[-1,1]){rails.push(box([.65,6.8,4.8],[sign*4.675,-3.2,0],'real side wall'));rails.push(box([1.1,6.8,.6],[sign*4.1,-3.2,2.1],'retaining rail'));}const floor=box([8.7,6.8,.6],[0,-3.2,-2.1],'real lower floor'),rear=box([8.7,.65,4.2],[0,-6.275,0],'recessed dielectric back'),bridge=box([3.6,1,.4],[0,-2.3,2.2],'retaining tongue'),contacts=[],tails=[];for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(box([.42,5.1,.42],[x,-3.2,.05],'actual contact '+(i+1),metal));box([.42,2.7,.42],[x,-6.6,.05],'retained return '+(i+1),metal);tails.push(mesh(host.body,new THREE.CylinderGeometry(.2,.2,3.2,24).rotateX(Math.PI/2),metal,[-6-x,-20,-2.0],'CatM GNSS actual four Grove solder tails'));}const port=host.add(new Port({id:'grove',label:'PORT.C UART · G/5/R/T',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,4.8],pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:2,center:[0,.05],order:col=>col+1},meta:{role:'visual-connector',face:'bottom',scope:'Actual four contacts and cable pose only;no UART/AT/electrical behavior.'}}));return{frame,rails,floor,rear,bridge,contacts,tails,port};}
export function sma(host,id,position){const frame=new THREE.Group();frame.name='CatM GNSS own '+id+' ordinary female SMA';frame.position.set(position[0],0,position[2]);host.body.add(frame);const gold=materials.metal(0xc4ab53,{roughness:.42}),ptfe=materials.plastic(0xe3dfc0),base=mesh(frame,new THREE.CylinderGeometry(2.85,2.85,5.0,48),gold,[0,23.4,0],'CatM GNSS '+id+' real gold cylindrical installation backstop'),foot=slab(frame,6,4.9,.65,.2,[0,23.2,-6.8],gold,[],0);foot.name='CatM GNSS '+id+' actual solder foot';const installation=slab(frame,5.6,5.3,4.1,.35,[0,22.9,-2.5],gold,[],0);installation.name='CatM GNSS '+id+' actual square SMA installationbody,ownphoto-derived seating';const legs=[];for(const x of[-2.5,2.5])for(const y of[21,24.6])legs.push(mesh(frame,new THREE.BoxGeometry(.5,.6,4.5),gold,[x,y,-4.45],'CatM GNSS '+id+' actual inferred retainedSMA PCBleg'));const shaft=ringY(frame,3.08,2.32,5.6,28,gold,'CatM GNSS '+id+' bored ordinary SMA outer thread'),dielectric=ringY(frame,2.31,.65,6.7,26.2,ptfe,'CatM GNSS '+id+' real centre-bored dielectric'),contact=ringY(frame,.6,.29,5.3,26.6,gold,'CatM GNSS '+id+' actual hollow female centre contact');class Thread extends THREE.Curve{getPoint(t,v=new THREE.Vector3()){const a=t*tau*8;return v.set(Math.cos(a)*3.105,28.35+t*4.9,Math.sin(a)*3.105);}}const neck=ringY(frame,2.7,2.32,2.1,25.9,gold,'CatM GNSS '+id+' actual narrow unthreaded SMA seatingneck');const thread=mesh(frame,cappedSweep(new Thread(),.07,192,8),gold,[0,0,0],'CatM GNSS '+id+' closed external thread appearance');const port=host.add(new Port({id,label:id==='lte'?'LTE ordinary SMA female':'GNSS ordinary SMA female',connector:'sma-female',position,hitSize:[6.35,1,6.35],meta:{role:'visual-connector',face:'top',physicalConnector:'sma-female',scope:'Mechanical connector only;no RF,GNSSposition,network or electrical behavior.'}}));return{frame,base,foot,installation,legs,neck,shaft,dielectric,contact,thread,port};}
export function dc(host){const frame=new THREE.Group();frame.name='CatM GNSS actual deep 5.5/2.1 DC receiving socket';frame.position.fromArray(spec.dc.position);host.body.add(frame);const black=materials.plastic(0x161b18),metal=materials.metal(0xb9b9a3),profile=roundedRect(8.4,6.2,.15);hole(profile,0,0,2.75);const body=solid(frame,profile,8.9,[0,0,0],black,'CatM GNSS real DC barrel housing with empty deep bore');body.geometry.rotateX(-Math.PI/2);const ring=ringY(frame,3,2.75,.35,0,black,'CatM GNSS real DC circular mouth lip'),back=mesh(frame,new THREE.BoxGeometry(8.4,.65,6.2),black,[0,8.575,0],'CatM GNSS actual DC cavity dielectric end wall'),contact=ringY(frame,2.73,2.55,5.5,2.4,metal,'CatM GNSS DC recessed outer sleeve contact'),pin=mesh(frame,new THREE.CylinderGeometry(1.05,1.05,6.6,40),metal,[0,5.4,0],'CatM GNSS actual2.1mm DC solid centre pin'),tip=mesh(frame,new THREE.SphereGeometry(1.05,32,16),metal,[0,2.1,0],'CatM GNSS rounded actual DCpin tip'),tails=[];for(const x of[-3,3])tails.push(mesh(host.body,new THREE.BoxGeometry(.7,1.2,1.8),metal,[6.2+x,-20,-3.25],'CatM GNSS actual retained DC board tab'));const port=host.add(new Port({id:'dc',label:'DC 9–24V · 5.5/2.1mm',connector:'dc-5.5-2.1',position:spec.dc.position,quaternion:portQuaternion('bottom'),hitSize:[8.4,1,6.2],meta:{role:'visual-connector',scope:'Passive physical barrel interface only;no voltage,supply orcurrent simulation.'}}));return{frame,body,ring,back,contact,pin,tip,tails,port};}
